# ═══════════════════════════════════════════════════════════════
# FinScore AI — Application Configuration
# ═══════════════════════════════════════════════════════════════
# ALL values sourced from environment variables.
# ZERO hardcoded credentials or connection strings.
# ═══════════════════════════════════════════════════════════════

# ─── Server ──────────────────────────────────────────────────
server.port=${PORT:8080}

# ─── Database (MySQL) ────────────────────────────────────────
# Default falls back to H2 in-memory if DB_URL not set (for dev)
spring.datasource.url=${DB_URL:jdbc:h2:mem:finscoreai}
spring.datasource.username=${DB_USERNAME:sa}
spring.datasource.password=${DB_PASSWORD:}
spring.datasource.driver-class-name=${DB_DRIVER:org.h2.Driver}

# JPA / Hibernate
spring.jpa.hibernate.ddl-auto=update
spring.jpa.show-sql=false
spring.jpa.properties.hibernate.format_sql=true
spring.jpa.properties.hibernate.dialect=${DB_DIALECT:org.hibernate.dialect.H2Dialect}

# H2 Console (dev only — disable in production)
spring.h2.console.enabled=${H2_CONSOLE:true}
spring.h2.console.path=/h2-console

# ─── ML Service ──────────────────────────────────────────────
ml.service.url=${ML_SERVICE_URL:http://localhost:8000}

# ─── Gemini API ──────────────────────────────────────────────
gemini.api.key=${GEMINI_API_KEY:}
gemini.api.model=${GEMINI_MODEL:gemini-1.5-flash}

# ─── Spring Security ────────────────────────────────────────
# Dashboard admin credentials from environment
spring.security.user.name=${ADMIN_USERNAME:admin}
spring.security.user.password=${ADMIN_PASSWORD:admin123}

# ─── Thymeleaf ───────────────────────────────────────────────
spring.thymeleaf.cache=false
spring.thymeleaf.prefix=classpath:/templates/
spring.thymeleaf.suffix=.html

# ─── Logging ─────────────────────────────────────────────────
logging.level.com.finscore=INFO
logging.level.org.springframework.security=WARN
logging.pattern.console=%d{HH:mm:ss.SSS} [%thread] %-5level %logger{36} - %msg%n

package com.finscore;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * FinScore AI — Main Application Entry Point
 * ============================================
 * Spring Boot application for alternate credit scoring targeting
 * 190M+ unbanked rural Indians using XGBoost ML + Gemini GenAI + RAG.
 * 
 * Starts embedded Tomcat, initializes JPA/Hibernate for MySQL,
 * configures Spring Security for dashboard protection, and
 * serves Thymeleaf templates for the frontend.
 * 
 * @author FinScore AI Team
 * @version 1.0.0
 */
@SpringBootApplication
public class FinScoreAiApplication {

    public static void main(String[] args) {
        SpringApplication.run(FinScoreAiApplication.class, args);
    }
}

package com.finscore.model;

import jakarta.persistence.*;
import jakarta.validation.constraints.*;
import lombok.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * BorrowerInput — JPA Entity for Borrower Assessments
 * =====================================================
 * Maps to the 'borrower_assessments' table in MySQL.
 * 
 * Contains both INPUT fields (borrower data from the form)
 * and OUTPUT fields (ML prediction results, Gemini explanations,
 * RAG tips). This dual-purpose design allows a single entity
 * to represent the complete assessment lifecycle.
 * 
 * PRIVACY NOTE:
 * This entity deliberately does NOT store Aadhaar, PAN, or
 * any biometric data. Only alternate financial behavior data
 * and the borrower's name are stored.
 * 
 * @author FinScore AI Team
 */
@Entity
@Table(name = "borrower_assessments")
@Getter @Setter
@NoArgsConstructor @AllArgsConstructor
@Builder
public class BorrowerInput {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // ═══ BORROWER INPUT FIELDS ═══════════════════════════════════════════

    /** Full name of the borrower (no Aadhaar/PAN stored) */
    @NotBlank(message = "Full name is required")
    @Size(max = 100, message = "Name must be under 100 characters")
    @Column(name = "full_name", nullable = false, length = 100)
    private String fullName;

    /** Gender — included for demographic tracking, NOT for scoring bias */
    @Column(name = "gender", length = 20)
    private String gender;

    /** Indian state or UT where borrower resides */
    @NotBlank(message = "State is required")
    @Column(name = "state", nullable = false, length = 50)
    private String state;

    /** Borrower's primary occupation */
    @NotBlank(message = "Occupation is required")
    @Column(name = "occupation", nullable = false, length = 50)
    private String occupation;

    /** Monthly income from all informal sources (INR) */
    @NotNull(message = "Monthly income is required")
    @DecimalMin(value = "0", message = "Income must be positive")
    @Column(name = "monthly_income", nullable = false, precision = 10, scale = 2)
    private BigDecimal monthlyIncome;

    /** Number of UPI transactions per month */
    @NotNull(message = "UPI frequency is required")
    @Min(value = 0, message = "UPI frequency must be non-negative")
    @Column(name = "upi_frequency", nullable = false)
    private Integer upiFrequency;

    /** Average amount per UPI transaction (INR) */
    @NotNull(message = "Average UPI amount is required")
    @DecimalMin(value = "0", message = "UPI amount must be positive")
    @Column(name = "avg_upi_amount", nullable = false, precision = 10, scale = 2)
    private BigDecimal avgUpiAmount;

    /** Utility bill payment consistency level */
    @NotBlank(message = "Utility consistency is required")
    @Column(name = "utility_consistency", nullable = false, length = 30)
    private String utilityConsistency;

    /** Monthly mobile recharge amount (INR) */
    @NotNull(message = "Recharge amount is required")
    @DecimalMin(value = "0", message = "Recharge amount must be positive")
    @Column(name = "recharge_amount", nullable = false, precision = 10, scale = 2)
    private BigDecimal rechargeAmount;

    /** Agricultural yield in kg/season (optional, mainly for farmers) */
    @Column(name = "agricultural_yield", precision = 10, scale = 2)
    @Builder.Default
    private BigDecimal agriculturalYield = BigDecimal.ZERO;

    /** Loan amount requested by the borrower (INR) */
    @NotNull(message = "Loan amount is required")
    @DecimalMin(value = "1", message = "Loan amount must be positive")
    @Column(name = "loan_requested", nullable = false, precision = 12, scale = 2)
    private BigDecimal loanRequested;

    /** Preferred language for AI explanation (Hindi or English) */
    @Column(name = "preferred_language", length = 10)
    @Builder.Default
    private String preferredLanguage = "English";

    /** Whether borrower gave consent for data processing (MANDATORY) */
    @Column(name = "consent_given", nullable = false)
    @Builder.Default
    private Boolean consentGiven = false;

    // ═══ ASSESSMENT RESULT FIELDS ════════════════════════════════════════
    // These are populated after ML prediction and Gemini API calls

    /** Credit score from XGBoost model (0-100) */
    @Column(name = "credit_score")
    private Integer creditScore;

    /** Risk category: Low Risk, Medium Risk, High Risk */
    @Column(name = "risk_category", length = 20)
    private String riskCategory;

    /** Whether the borrower is eligible for a loan */
    @Column(name = "loan_eligible")
    private Boolean loanEligible;

    /** Maximum recommended loan amount (INR) */
    @Column(name = "max_loan_amount", precision = 12, scale = 2)
    private BigDecimal maxLoanAmount;

    /** Suggested interest rate range string */
    @Column(name = "suggested_interest_rate", length = 20)
    private String suggestedInterestRate;

    /** Gemini AI explanation in English */
    @Column(name = "gemini_explanation_en", columnDefinition = "TEXT")
    private String geminiExplanationEn;

    /** Gemini AI explanation in Hindi */
    @Column(name = "gemini_explanation_hi", columnDefinition = "TEXT")
    private String geminiExplanationHi;

    /** RAG-generated financial tips stored as JSON string */
    @Column(name = "rag_tips", columnDefinition = "TEXT")
    private String ragTips;

    /** ML model prediction confidence (0-1) */
    @Column(name = "ml_confidence", precision = 5, scale = 4)
    private BigDecimal mlConfidence;

    // ═══ METADATA ════════════════════════════════════════════════════════

    /** Timestamp when assessment was created */
    @Column(name = "created_at")
    @Builder.Default
    private LocalDateTime createdAt = LocalDateTime.now();

    /** IP address of the requester (for audit trail) */
    @Column(name = "ip_address", length = 45)
    private String ipAddress;

    /**
     * Set creation timestamp before persisting.
     * Ensures created_at is always populated.
     */
    @PrePersist
    protected void onCreate() {
        if (createdAt == null) {
            createdAt = LocalDateTime.now();
        }
    }
}

package com.finscore.model;

import lombok.*;
import java.math.BigDecimal;
import java.util.List;

/**
 * CreditResult — Data Transfer Object for API Responses
 * =======================================================
 * Carries the complete credit assessment result from the service
 * layer to the controller and then to the Thymeleaf templates
 * or JSON API consumers.
 * 
 * This DTO is separate from the JPA entity to decouple the
 * database schema from the API contract.
 * 
 * @author FinScore AI Team
 */
@Getter @Setter
@NoArgsConstructor @AllArgsConstructor
@Builder
public class CreditResult {

    /** Database ID of the saved assessment */
    private Long id;

    /** Borrower's full name */
    private String fullName;

    /** Borrower's occupation */
    private String occupation;

    /** Borrower's state */
    private String state;

    /** Borrower's gender */
    private String gender;

    /** Monthly income in INR */
    private BigDecimal monthlyIncome;

    /** Loan amount requested in INR */
    private BigDecimal loanRequested;

    // ═══ ML PREDICTION RESULTS ═══════════════════════════════════════════

    /** Credit score from XGBoost model (0-100) */
    private Integer creditScore;

    /** Risk category: "Low Risk", "Medium Risk", "High Risk" */
    private String riskCategory;

    /** Whether the borrower qualifies for a loan */
    private Boolean loanEligible;

    /** Maximum recommended loan amount in INR */
    private BigDecimal maxLoanAmount;

    /** Suggested interest rate range (e.g., "10-12% p.a.") */
    private String suggestedInterestRate;

    /** Model prediction confidence (0.0 - 1.0) */
    private BigDecimal mlConfidence;

    // ═══ GENAI EXPLANATION ═══════════════════════════════════════════════

    /** Gemini explanation in the borrower's preferred language */
    private String explanation;

    /** Current language of the explanation */
    private String explanationLanguage;

    // ═══ RAG TIPS ════════════════════════════════════════════════════════

    /** Personalized financial tips from RAG pipeline */
    private List<FinancialTip> tips;

    /**
     * Inner class representing a single financial tip.
     * Each tip has a heading, detail text, and icon class.
     */
    @Getter @Setter
    @NoArgsConstructor @AllArgsConstructor
    @Builder
    public static class FinancialTip {
        /** Short descriptive heading for the tip */
        private String heading;

        /** Detailed actionable advice */
        private String detail;

        /** Bootstrap icon class name (e.g., "bi-piggy-bank") */
        private String icon;
    }
}

package com.finscore.repository;

import com.finscore.model.BorrowerInput;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;

/**
 * BorrowerRepository — Data Access Layer for Assessments
 * ========================================================
 * JPA repository providing CRUD operations and custom queries
 * for the borrower_assessments table.
 * 
 * Custom queries support the dashboard's statistical charts
 * and the paginated assessment history endpoint.
 * 
 * @author FinScore AI Team
 */
@Repository
public interface BorrowerRepository extends JpaRepository<BorrowerInput, Long> {

    // ═══ FILTERED QUERIES ════════════════════════════════════════════════

    /** Find assessments by state with pagination */
    Page<BorrowerInput> findByState(String state, Pageable pageable);

    /** Find assessments by occupation with pagination */
    Page<BorrowerInput> findByOccupation(String occupation, Pageable pageable);

    /** Find assessments by risk category with pagination */
    Page<BorrowerInput> findByRiskCategory(String riskCategory, Pageable pageable);

    /** Find assessments by state and occupation with pagination */
    Page<BorrowerInput> findByStateAndOccupation(String state, String occupation, Pageable pageable);

    // ═══ DASHBOARD STATISTICS ════════════════════════════════════════════

    /** Total number of completed assessments */
    @Query("SELECT COUNT(b) FROM BorrowerInput b WHERE b.creditScore IS NOT NULL")
    Long countCompletedAssessments();

    /** Average credit score across all assessments */
    @Query("SELECT COALESCE(AVG(b.creditScore), 0) FROM BorrowerInput b WHERE b.creditScore IS NOT NULL")
    Double getAverageCreditScore();

    /** Loan eligibility rate as percentage */
    @Query("SELECT COALESCE(COUNT(CASE WHEN b.loanEligible = true THEN 1 END) * 100.0 / NULLIF(COUNT(b), 0), 0) " +
           "FROM BorrowerInput b WHERE b.creditScore IS NOT NULL")
    Double getLoanEligibilityRate();

    /** Most common occupation among assessed borrowers */
    @Query("SELECT b.occupation FROM BorrowerInput b WHERE b.creditScore IS NOT NULL " +
           "GROUP BY b.occupation ORDER BY COUNT(b) DESC LIMIT 1")
    String getMostCommonOccupation();

    // ═══ CHART DATA QUERIES ═════════════════════════════════════════════

    /** Score distribution — count of assessments in each score bucket */
    @Query("SELECT " +
           "CASE " +
           "  WHEN b.creditScore BETWEEN 0 AND 10 THEN '0-10' " +
           "  WHEN b.creditScore BETWEEN 11 AND 20 THEN '11-20' " +
           "  WHEN b.creditScore BETWEEN 21 AND 30 THEN '21-30' " +
           "  WHEN b.creditScore BETWEEN 31 AND 40 THEN '31-40' " +
           "  WHEN b.creditScore BETWEEN 41 AND 50 THEN '41-50' " +
           "  WHEN b.creditScore BETWEEN 51 AND 60 THEN '51-60' " +
           "  WHEN b.creditScore BETWEEN 61 AND 70 THEN '61-70' " +
           "  WHEN b.creditScore BETWEEN 71 AND 80 THEN '71-80' " +
           "  WHEN b.creditScore BETWEEN 81 AND 90 THEN '81-90' " +
           "  ELSE '91-100' " +
           "END AS bucket, COUNT(b) " +
           "FROM BorrowerInput b WHERE b.creditScore IS NOT NULL " +
           "GROUP BY bucket ORDER BY bucket")
    List<Object[]> getScoreDistribution();

    /** Average score by state */
    @Query("SELECT b.state, AVG(b.creditScore) " +
           "FROM BorrowerInput b WHERE b.creditScore IS NOT NULL " +
           "GROUP BY b.state ORDER BY AVG(b.creditScore) DESC")
    List<Object[]> getAverageScoreByState();

    /** Average score by occupation */
    @Query("SELECT b.occupation, AVG(b.creditScore) " +
           "FROM BorrowerInput b WHERE b.creditScore IS NOT NULL " +
           "GROUP BY b.occupation ORDER BY AVG(b.creditScore) DESC")
    List<Object[]> getAverageScoreByOccupation();

    /** Average score by gender — for bias monitoring dashboard */
    @Query("SELECT b.gender, AVG(b.creditScore), COUNT(b) " +
           "FROM BorrowerInput b WHERE b.creditScore IS NOT NULL AND b.gender IS NOT NULL " +
           "GROUP BY b.gender")
    List<Object[]> getAverageScoreByGender();

    /** Daily assessment volume for the last 30 days */
    @Query(value = "SELECT DATE(created_at) as day, COUNT(*) " +
           "FROM borrower_assessments " +
           "WHERE credit_score IS NOT NULL AND created_at >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) " +
           "GROUP BY day ORDER BY day", nativeQuery = true)
    List<Object[]> getDailyVolume();

    /** Count by risk category */
    @Query("SELECT b.riskCategory, COUNT(b) FROM BorrowerInput b " +
           "WHERE b.creditScore IS NOT NULL GROUP BY b.riskCategory")
    List<Object[]> getCountByRiskCategory();

    /** Recent assessments ordered by creation date */
    Page<BorrowerInput> findAllByOrderByCreatedAtDesc(Pageable pageable);
}

package com.finscore.service;

import com.finscore.model.BorrowerInput;
import com.finscore.model.CreditResult;
import com.finscore.repository.BorrowerRepository;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.*;

/**
 * CreditScoringService — Core Business Logic Orchestrator
 * =========================================================
 * Orchestrates the complete credit assessment pipeline:
 * 
 * 1. Validate consent flag
 * 2. Call Python ML service (XGBoost) for score prediction
 * 3. Call Gemini API for explanation in preferred language
 * 4. Call RAG service for personalized financial tips
 * 5. Save complete result to MySQL database
 * 6. Return structured CreditResult
 * 
 * Each external service call is wrapped in try-catch with
 * graceful fallback behavior — the assessment still succeeds
 * even if Gemini or RAG services are temporarily unavailable.
 * 
 * @author FinScore AI Team
 */
@Service
@Slf4j
@RequiredArgsConstructor
public class CreditScoringService {

    private final BorrowerRepository borrowerRepository;
    private final GeminiService geminiService;
    private final RAGService ragService;
    private final RestTemplate restTemplate;
    private final ObjectMapper objectMapper;

    @Value("${ml.service.url}")
    private String mlServiceUrl;

    /**
     * Process a complete credit assessment.
     * 
     * This is the main entry point for the scoring pipeline.
     * Steps are executed sequentially with fallbacks at each stage.
     * 
     * @param input Validated borrower input from the form
     * @return CreditResult with score, explanation, and tips
     * @throws IllegalArgumentException if consent is not given
     */
    public CreditResult processAssessment(BorrowerInput input) {
        // ── Step 1: Validate consent ────────────────────────────────────
        if (input.getConsentGiven() == null || !input.getConsentGiven()) {
            throw new IllegalArgumentException(
                "Consent is required before processing. " +
                "Please check the consent checkbox."
            );
        }

        log.info("Processing assessment for: {} ({})", 
                 input.getFullName(), input.getOccupation());

        // ── Step 2: Call ML Service for prediction ──────────────────────
        Map<String, Object> mlResult = callMLService(input);

        int creditScore = ((Number) mlResult.getOrDefault("score", 50)).intValue();
        String riskCategory = (String) mlResult.getOrDefault("risk_category", "Medium Risk");
        boolean loanEligible = (Boolean) mlResult.getOrDefault("loan_eligible", false);
        double maxLoanAmount = ((Number) mlResult.getOrDefault("max_loan_amount", 0)).doubleValue();
        String interestRate = (String) mlResult.getOrDefault("suggested_interest_rate", "N/A");
        double confidence = ((Number) mlResult.getOrDefault("confidence", 0.75)).doubleValue();

        // Update input entity with results
        input.setCreditScore(creditScore);
        input.setRiskCategory(riskCategory);
        input.setLoanEligible(loanEligible);
        input.setMaxLoanAmount(BigDecimal.valueOf(maxLoanAmount));
        input.setSuggestedInterestRate(interestRate);
        input.setMlConfidence(BigDecimal.valueOf(confidence).setScale(4, RoundingMode.HALF_UP));

        // ── Step 3: Call Gemini for explanation ─────────────────────────
        String preferredLang = input.getPreferredLanguage() != null 
            ? input.getPreferredLanguage() : "English";

        String explanation = geminiService.generateExplanation(
            input.getOccupation(),
            input.getState(),
            input.getMonthlyIncome().intValue(),
            creditScore,
            riskCategory,
            input.getLoanRequested().intValue(),
            preferredLang
        );

        // Store explanations in both languages if possible
        if ("Hindi".equalsIgnoreCase(preferredLang)) {
            input.setGeminiExplanationHi(explanation);
        } else {
            input.setGeminiExplanationEn(explanation);
        }

        // ── Step 4: Call RAG service for tips ───────────────────────────
        List<CreditResult.FinancialTip> tips = ragService.getFinancialTips(
            creditScore, input.getOccupation(), input.getState()
        );

        // Serialize tips to JSON string for database storage
        try {
            input.setRagTips(objectMapper.writeValueAsString(tips));
        } catch (Exception e) {
            log.warn("Failed to serialize RAG tips: {}", e.getMessage());
            input.setRagTips("[]");
        }

        // ── Step 5: Save to database ────────────────────────────────────
        BorrowerInput saved = borrowerRepository.save(input);
        log.info("Assessment saved with ID: {} | Score: {} | Risk: {}", 
                 saved.getId(), creditScore, riskCategory);

        // ── Step 6: Build and return CreditResult DTO ──────────────────
        return CreditResult.builder()
                .id(saved.getId())
                .fullName(saved.getFullName())
                .occupation(saved.getOccupation())
                .state(saved.getState())
                .gender(saved.getGender())
                .monthlyIncome(saved.getMonthlyIncome())
                .loanRequested(saved.getLoanRequested())
                .creditScore(creditScore)
                .riskCategory(riskCategory)
                .loanEligible(loanEligible)
                .maxLoanAmount(BigDecimal.valueOf(maxLoanAmount))
                .suggestedInterestRate(interestRate)
                .mlConfidence(BigDecimal.valueOf(confidence))
                .explanation(explanation)
                .explanationLanguage(preferredLang)
                .tips(tips)
                .build();
    }

    /**
     * Call the Python ML service for credit score prediction.
     * 
     * Sends borrower's alternate financial data to the XGBoost model
     * via the FastAPI /predict endpoint.
     * 
     * @param input Borrower input data
     * @return Map with prediction results (score, risk, eligibility, etc.)
     */
    private Map<String, Object> callMLService(BorrowerInput input) {
        String predictUrl = mlServiceUrl + "/predict";

        try {
            // Build request body matching the Python PredictRequest schema
            Map<String, Object> requestBody = new HashMap<>();
            requestBody.put("monthly_income", input.getMonthlyIncome().doubleValue());
            requestBody.put("upi_frequency", input.getUpiFrequency());
            requestBody.put("avg_upi_amount", input.getAvgUpiAmount().doubleValue());
            requestBody.put("utility_consistency", input.getUtilityConsistency());
            requestBody.put("recharge_amount", input.getRechargeAmount().doubleValue());
            requestBody.put("agricultural_yield", 
                input.getAgriculturalYield() != null 
                    ? input.getAgriculturalYield().doubleValue() : 0.0);
            requestBody.put("loan_requested", input.getLoanRequested().doubleValue());
            requestBody.put("occupation", input.getOccupation());
            requestBody.put("state", input.getState());
            requestBody.put("gender", input.getGender() != null ? input.getGender() : "Other");

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.APPLICATION_JSON);
            HttpEntity<Map<String, Object>> entity = new HttpEntity<>(requestBody, headers);

            log.info("Calling ML service at: {}", predictUrl);
            ResponseEntity<String> response = restTemplate.postForEntity(
                predictUrl, entity, String.class
            );

            if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
                return objectMapper.readValue(
                    response.getBody(), 
                    new TypeReference<Map<String, Object>>() {}
                );
            }

            log.warn("ML service returned non-success status: {}", response.getStatusCode());

        } catch (Exception e) {
            log.error("ML service call failed: {} — using fallback scoring", e.getMessage());
        }

        // ── Fallback: Simple rule-based scoring if ML service is down ──
        return fallbackScoring(input);
    }

    /**
     * Fallback scoring when ML service is unavailable.
     * 
     * Uses a simple weighted formula based on the same alternate
     * financial indicators. This ensures the application remains
     * functional even if the Python service is temporarily down.
     */
    private Map<String, Object> fallbackScoring(BorrowerInput input) {
        log.warn("Using fallback scoring — ML service unavailable");

        double incomeNorm = Math.min(input.getMonthlyIncome().doubleValue() / 50000.0, 1.0);
        double upiNorm = Math.min(input.getUpiFrequency() / 100.0, 1.0);
        double upiAmtNorm = Math.min(input.getAvgUpiAmount().doubleValue() / 5000.0, 1.0);

        double utilityScore = switch (input.getUtilityConsistency()) {
            case "Always on time" -> 1.0;
            case "Sometimes late" -> 0.5;
            default -> 0.15;
        };

        double rechargeNorm = Math.min(input.getRechargeAmount().doubleValue() / 500.0, 1.0);

        double rawScore = 0.25 * incomeNorm + 0.20 * upiNorm + 0.15 * upiAmtNorm 
                        + 0.20 * utilityScore + 0.10 * rechargeNorm + 0.10 * 0.5;

        int score = (int) Math.min(Math.max(rawScore * 100, 0), 100);
        String risk = score >= 70 ? "Low Risk" : (score >= 40 ? "Medium Risk" : "High Risk");
        boolean eligible = score >= 30;
        double maxLoan = eligible 
            ? Math.min(input.getMonthlyIncome().doubleValue() * (6 + score * 0.18), 
                       input.getLoanRequested().doubleValue()) 
            : 0;

        String interestRate = score >= 70 ? "10-12% p.a." 
            : (score >= 50 ? "14-16% p.a." : (score >= 30 ? "18-22% p.a." : "Not recommended"));

        Map<String, Object> result = new HashMap<>();
        result.put("score", score);
        result.put("risk_category", risk);
        result.put("loan_eligible", eligible);
        result.put("max_loan_amount", maxLoan);
        result.put("suggested_interest_rate", interestRate);
        result.put("confidence", 0.60); // Lower confidence for fallback
        return result;
    }

    /**
     * Retrieve a saved assessment by ID.
     * 
     * @param id Assessment database ID
     * @return CreditResult DTO or null if not found
     */
    public CreditResult getAssessmentById(Long id) {
        return borrowerRepository.findById(id)
            .map(this::entityToResult)
            .orElse(null);
    }

    /**
     * Convert a BorrowerInput entity to a CreditResult DTO.
     * Deserializes the JSON-stored RAG tips back into objects.
     */
    private CreditResult entityToResult(BorrowerInput entity) {
        List<CreditResult.FinancialTip> tips = new ArrayList<>();

        // Deserialize RAG tips from JSON string
        if (entity.getRagTips() != null && !entity.getRagTips().isEmpty()) {
            try {
                tips = objectMapper.readValue(
                    entity.getRagTips(),
                    new TypeReference<List<CreditResult.FinancialTip>>() {}
                );
            } catch (Exception e) {
                log.warn("Failed to deserialize RAG tips for assessment {}: {}", 
                         entity.getId(), e.getMessage());
            }
        }

        // Determine which explanation to use
        String explanation = entity.getGeminiExplanationEn();
        String lang = "English";
        if ("Hindi".equalsIgnoreCase(entity.getPreferredLanguage()) 
            && entity.getGeminiExplanationHi() != null) {
            explanation = entity.getGeminiExplanationHi();
            lang = "Hindi";
        }

        return CreditResult.builder()
                .id(entity.getId())
                .fullName(entity.getFullName())
                .occupation(entity.getOccupation())
                .state(entity.getState())
                .gender(entity.getGender())
                .monthlyIncome(entity.getMonthlyIncome())
                .loanRequested(entity.getLoanRequested())
                .creditScore(entity.getCreditScore())
                .riskCategory(entity.getRiskCategory())
                .loanEligible(entity.getLoanEligible())
                .maxLoanAmount(entity.getMaxLoanAmount())
                .suggestedInterestRate(entity.getSuggestedInterestRate())
                .mlConfidence(entity.getMlConfidence())
                .explanation(explanation)
                .explanationLanguage(lang)
                .tips(tips)
                .build();
    }
}

package com.finscore.service;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

import java.util.*;

/**
 * GeminiService — Google Gemini AI Integration
 * ===============================================
 * Calls the Gemini 1.5 Flash model to generate empathetic,
 * plain-language explanations of credit scores.
 * 
 * The prompt is designed to be:
 * - Compassionate and non-judgmental
 * - Written in simple everyday language
 * - Actionable with specific improvement steps
 * - Available in both Hindi and English
 * - Mentioning relevant government schemes
 * 
 * API key is sourced from environment variable GEMINI_API_KEY.
 * If the key is missing or the API fails, a graceful fallback
 * explanation is returned.
 * 
 * @author FinScore AI Team
 */
@Service
@Slf4j
@RequiredArgsConstructor
public class GeminiService {

    private final RestTemplate restTemplate;
    private final ObjectMapper objectMapper;

    @Value("${gemini.api.key:}")
    private String apiKey;

    @Value("${gemini.api.model:gemini-1.5-flash}")
    private String model;

    /** Gemini API base URL */
    private static final String GEMINI_API_URL = 
        "https://generativelanguage.googleapis.com/v1beta/models/%s:generateContent?key=%s";

    /**
     * Generate a credit score explanation using Gemini AI.
     * 
     * @param occupation  Borrower's occupation
     * @param state       Borrower's state
     * @param income      Monthly income in INR
     * @param score       Credit score (0-100)
     * @param riskCategory Risk category string
     * @param loanRequested Loan amount requested
     * @param language    Target language: "Hindi" or "English"
     * @return Plain text explanation in the requested language
     */
    public String generateExplanation(
            String occupation, String state, int income,
            int score, String riskCategory, int loanRequested,
            String language) {

        // Check if API key is available
        if (apiKey == null || apiKey.isBlank()) {
            log.warn("Gemini API key not configured — using fallback explanation");
            return generateFallbackExplanation(
                occupation, score, riskCategory, loanRequested, language
            );
        }

        try {
            // Build the empathetic prompt
            String prompt = buildPrompt(
                occupation, state, income, score, 
                riskCategory, loanRequested, language
            );

            // Build Gemini API request body
            Map<String, Object> requestBody = buildRequestBody(prompt);

            String url = String.format(GEMINI_API_URL, model, apiKey);

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.APPLICATION_JSON);
            HttpEntity<Map<String, Object>> entity = new HttpEntity<>(requestBody, headers);

            log.info("Calling Gemini API for {} explanation (score: {})", language, score);

            ResponseEntity<String> response = restTemplate.postForEntity(
                url, entity, String.class
            );

            if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
                return extractTextFromResponse(response.getBody());
            }

            log.warn("Gemini API returned status: {}", response.getStatusCode());

        } catch (Exception e) {
            log.error("Gemini API call failed: {}", e.getMessage());
        }

        // Fallback if API call fails
        return generateFallbackExplanation(
            occupation, score, riskCategory, loanRequested, language
        );
    }

    /**
     * Build the empathetic prompt template for Gemini.
     * 
     * The prompt is carefully crafted to produce explanations that
     * a person with basic literacy can understand. It avoids financial
     * jargon and uses an encouraging, supportive tone.
     */
    private String buildPrompt(
            String occupation, String state, int income,
            int score, String riskCategory, int loanRequested,
            String language) {

        return String.format("""
            You are a compassionate financial advisor helping rural Indians
            understand their credit assessment result.

            Borrower Profile:
            - Occupation: %s
            - State: %s
            - Monthly Income: ₹%,d
            - Credit Score: %d out of 100
            - Risk Category: %s
            - Loan Requested: ₹%,d

            Task: Explain this credit score result in simple %s language
            that a person with basic literacy can understand.

            Instructions:
            - Start with an encouraging, empathetic opening
            - Explain what the score means in practical terms
            - Give 3 specific actionable steps to improve their score
            - Mention one relevant government scheme they may qualify for
            - End with an encouraging closing message
            - Keep total response under 200 words
            - Use simple everyday words, avoid financial jargon
            - If language is Hindi, respond entirely in Hindi (Devanagari script)
            - Do NOT use markdown formatting, bullet points with *, or headers
            - Write in plain paragraphs with numbered steps
            """,
            occupation, state, income, score, riskCategory, loanRequested, language
        );
    }

    /**
     * Build the Gemini API request body in the required format.
     */
    private Map<String, Object> buildRequestBody(String prompt) {
        Map<String, Object> textPart = new HashMap<>();
        textPart.put("text", prompt);

        Map<String, Object> contentParts = new HashMap<>();
        contentParts.put("parts", List.of(textPart));

        Map<String, Object> generationConfig = new HashMap<>();
        generationConfig.put("temperature", 0.7);
        generationConfig.put("maxOutputTokens", 500);
        generationConfig.put("topP", 0.9);

        Map<String, Object> requestBody = new HashMap<>();
        requestBody.put("contents", List.of(contentParts));
        requestBody.put("generationConfig", generationConfig);

        return requestBody;
    }

    /**
     * Extract the generated text from Gemini's JSON response.
     */
    private String extractTextFromResponse(String responseBody) {
        try {
            JsonNode root = objectMapper.readTree(responseBody);
            JsonNode candidates = root.path("candidates");

            if (candidates.isArray() && candidates.size() > 0) {
                JsonNode content = candidates.get(0).path("content");
                JsonNode parts = content.path("parts");

                if (parts.isArray() && parts.size() > 0) {
                    return parts.get(0).path("text").asText();
                }
            }

            log.warn("Unexpected Gemini response structure");
        } catch (Exception e) {
            log.error("Failed to parse Gemini response: {}", e.getMessage());
        }

        return null;
    }

    /**
     * Generate a fallback explanation when Gemini API is unavailable.
     * 
     * Provides a helpful, empathetic explanation based on the score
     * and risk category. Available in both Hindi and English.
     */
    private String generateFallbackExplanation(
            String occupation, int score, String riskCategory,
            int loanRequested, String language) {

        if ("Hindi".equalsIgnoreCase(language)) {
            return generateHindiFallback(occupation, score, riskCategory, loanRequested);
        }
        return generateEnglishFallback(occupation, score, riskCategory, loanRequested);
    }

    private String generateEnglishFallback(
            String occupation, int score, String riskCategory, int loanRequested) {

        StringBuilder sb = new StringBuilder();

        if (score >= 70) {
            sb.append("Great news! Your credit score of ").append(score)
              .append(" out of 100 shows that you have strong financial habits. ")
              .append("As a ").append(occupation).append(", your consistent financial behavior ")
              .append("makes you eligible for a loan. ");
        } else if (score >= 40) {
            sb.append("Your credit score is ").append(score)
              .append(" out of 100, which shows moderate financial activity. ")
              .append("As a ").append(occupation).append(", you have a good foundation ")
              .append("but there are ways to improve your score. ");
        } else {
            sb.append("Your credit score is ").append(score)
              .append(" out of 100. While this score is currently low, ")
              .append("please don't worry — there are simple steps you can take ")
              .append("to improve it. As a ").append(occupation)
              .append(", you have opportunities to build your financial profile. ");
        }

        sb.append("\n\nHere are 3 steps to improve your score:\n")
          .append("1. Use UPI for daily payments — even small amounts help build your financial trail.\n")
          .append("2. Pay electricity and phone bills on time every month.\n")
          .append("3. Save a small amount regularly in your bank account.\n\n");

        sb.append("You may also benefit from the Pradhan Mantri MUDRA Yojana, ")
          .append("which provides loans up to ₹50,000 without any guarantee. ")
          .append("Keep up your good work and your score will improve!");

        return sb.toString();
    }

    private String generateHindiFallback(
            String occupation, int score, String riskCategory, int loanRequested) {

        StringBuilder sb = new StringBuilder();

        if (score >= 70) {
            sb.append("बहुत अच्छी खबर! आपका क्रेडिट स्कोर ").append(score)
              .append(" है जो 100 में से बहुत अच्छा है। ")
              .append("आपकी वित्तीय आदतें मजबूत हैं और आप ऋण के लिए पात्र हैं। ");
        } else if (score >= 40) {
            sb.append("आपका क्रेडिट स्कोर ").append(score)
              .append(" है जो 100 में से ठीक है। ")
              .append("आपके पास अच्छी नींव है लेकिन स्कोर बेहतर करने के तरीके हैं। ");
        } else {
            sb.append("आपका क्रेडिट स्कोर ").append(score)
              .append(" है। चिंता न करें — कुछ आसान कदम उठाकर ")
              .append("आप इसे बेहतर बना सकते हैं। ");
        }

        sb.append("\n\nस्कोर सुधारने के 3 उपाय:\n")
          .append("1. रोजमर्रा के भुगतान के लिए UPI का उपयोग करें।\n")
          .append("2. बिजली और फोन का बिल हर महीने समय पर भरें।\n")
          .append("3. बैंक खाते में नियमित रूप से छोटी बचत करें।\n\n");

        sb.append("प्रधानमंत्री मुद्रा योजना के तहत आप बिना गारंटी ")
          .append("₹50,000 तक का ऋण प्राप्त कर सकते हैं। ")
          .append("हिम्मत रखें, आपका स्कोर जरूर सुधरेगा!");

        return sb.toString();
    }
}

package com.finscore.service;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.finscore.model.CreditResult;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

import java.util.*;

/**
 * RAGService — Retrieval-Augmented Generation Tips Client
 * =========================================================
 * Calls the Python FastAPI /rag/tips endpoint to retrieve
 * personalized financial tips from the FAISS vector store.
 * 
 * Tips are based on RBI financial inclusion guidelines and
 * are personalized to the borrower's occupation and score range.
 * 
 * Falls back to hardcoded tips if the Python service is unavailable.
 * 
 * @author FinScore AI Team
 */
@Service
@Slf4j
@RequiredArgsConstructor
public class RAGService {

    private final RestTemplate restTemplate;
    private final ObjectMapper objectMapper;

    @Value("${ml.service.url}")
    private String mlServiceUrl;

    /**
     * Get personalized financial tips from the RAG pipeline.
     * 
     * @param score      Credit score (0-100)
     * @param occupation Borrower's occupation
     * @param state      Borrower's state
     * @return List of 3 FinancialTip objects
     */
    public List<CreditResult.FinancialTip> getFinancialTips(
            int score, String occupation, String state) {

        String tipsUrl = mlServiceUrl + "/rag/tips";

        try {
            // Build request body
            Map<String, Object> requestBody = new HashMap<>();
            requestBody.put("score", score);
            requestBody.put("occupation", occupation);
            requestBody.put("state", state != null ? state : "");

            HttpHeaders headers = new HttpHeaders();
            headers.setContentType(MediaType.APPLICATION_JSON);
            HttpEntity<Map<String, Object>> entity = new HttpEntity<>(requestBody, headers);

            log.info("Calling RAG service for tips: occupation={}, score={}", occupation, score);

            ResponseEntity<String> response = restTemplate.postForEntity(
                tipsUrl, entity, String.class
            );

            if (response.getStatusCode().is2xxSuccessful() && response.getBody() != null) {
                return parseTipsResponse(response.getBody());
            }

            log.warn("RAG service returned status: {}", response.getStatusCode());

        } catch (Exception e) {
            log.error("RAG service call failed: {} — using fallback tips", e.getMessage());
        }

        // Return fallback tips if service is unavailable
        return getFallbackTips(score, occupation);
    }

    /**
     * Parse the JSON response from the RAG tips endpoint.
     * Expected format: { "tips": [{ "heading", "detail", "icon" }, ...] }
     */
    private List<CreditResult.FinancialTip> parseTipsResponse(String responseBody) {
        try {
            JsonNode root = objectMapper.readTree(responseBody);
            JsonNode tipsNode = root.path("tips");

            if (tipsNode.isArray()) {
                List<CreditResult.FinancialTip> tips = new ArrayList<>();
                for (JsonNode tipNode : tipsNode) {
                    tips.add(CreditResult.FinancialTip.builder()
                        .heading(tipNode.path("heading").asText("Financial Tip"))
                        .detail(tipNode.path("detail").asText(""))
                        .icon(tipNode.path("icon").asText("bi-lightbulb"))
                        .build()
                    );
                }
                return tips;
            }
        } catch (Exception e) {
            log.error("Failed to parse RAG tips response: {}", e.getMessage());
        }

        return getFallbackTips(50, "Unknown");
    }

    /**
     * Provide fallback tips when RAG service is unavailable.
     * 
     * Tips are categorized by score range to remain relevant
     * even without RAG retrieval.
     */
    private List<CreditResult.FinancialTip> getFallbackTips(int score, String occupation) {
        log.warn("Using fallback tips for {} (score: {})", occupation, score);

        List<CreditResult.FinancialTip> tips = new ArrayList<>();

        if (score >= 70) {
            tips.add(CreditResult.FinancialTip.builder()
                .heading("Maintain Your Strong Financial Habits")
                .detail("Your consistent UPI usage and bill payments show excellent financial discipline. "
                    + "Continue these habits to maintain your high credit score and access better loan terms.")
                .icon("bi-trophy")
                .build());

            tips.add(CreditResult.FinancialTip.builder()
                .heading("Explore MUDRA Yojana Benefits")
                .detail("With your strong credit profile, you may qualify for MUDRA loans up to ₹10 lakh "
                    + "for business expansion. Visit your nearest bank to learn about Shishu, Kishore, "
                    + "and Tarun loan categories.")
                .icon("bi-award")
                .build());

            tips.add(CreditResult.FinancialTip.builder()
                .heading("Build Emergency Savings")
                .detail("Set aside ₹500-1000 every month in your PMJDY account. This safety net "
                    + "protects you during emergencies and demonstrates savings discipline to lenders.")
                .icon("bi-piggy-bank")
                .build());

        } else if (score >= 40) {
            tips.add(CreditResult.FinancialTip.builder()
                .heading("Increase Your UPI Usage")
                .detail("Try to make at least 15-20 UPI transactions per month. Use UPI for buying "
                    + "groceries, paying for transport, and receiving payments for your work. "
                    + "Each transaction builds your digital financial trail.")
                .icon("bi-qr-code")
                .build());

            tips.add(CreditResult.FinancialTip.builder()
                .heading("Pay Bills Before Due Date")
                .detail("Set phone reminders for electricity and phone bill due dates. "
                    + "Paying on time for 6 months straight can significantly boost your credit score. "
                    + "Even partial payments before the due date are better than late payments.")
                .icon("bi-calendar-check")
                .build());

            tips.add(CreditResult.FinancialTip.builder()
                .heading("Join a Self Help Group")
                .detail("SHG membership helps you build savings habits and access small loans "
                    + "at low interest rates. Women SHGs have a 96% repayment rate — the highest "
                    + "in Indian microfinance. Contact your nearest NRLM block office to join.")
                .icon("bi-people")
                .build());

        } else {
            tips.add(CreditResult.FinancialTip.builder()
                .heading("Open a Jan Dhan Account")
                .detail("If you don't have a bank account, open a free PMJDY account at any bank. "
                    + "You'll get a free debit card and ₹2 lakh accident insurance. "
                    + "Make small regular deposits to start building your banking history.")
                .icon("bi-bank")
                .build());

            tips.add(CreditResult.FinancialTip.builder()
                .heading("Start Using Digital Payments")
                .detail("Download a UPI app (Google Pay, PhonePe, or Paytm) and start "
                    + "making small payments. Even ₹50-100 transactions help build your "
                    + "digital financial trail. Ask shop owners if they accept UPI.")
                .icon("bi-phone")
                .build());

            tips.add(CreditResult.FinancialTip.builder()
                .heading("Register on e-SHRAM Portal")
                .detail("Register at eshram.gov.in to get a unique worker ID and access "
                    + "government schemes including PM-KISAN (₹6,000/year), PMSBY insurance, "
                    + "and skill development programs that improve your financial profile.")
                .icon("bi-shield-check")
                .build());
        }

        return tips;
    }
}

package com.finscore.controller;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.finscore.model.BorrowerInput;
import com.finscore.model.CreditResult;
import com.finscore.repository.BorrowerRepository;
import com.finscore.service.CreditScoringService;
import com.finscore.service.GeminiService;
import jakarta.validation.Valid;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.*;

/**
 * CreditController — REST API Endpoints
 * ========================================
 * Handles all credit scoring API endpoints including:
 * - POST /api/credit/score — Submit assessment
 * - POST /api/credit/explain — Toggle explanation language
 * - GET  /api/credit/history — Paginated assessment history
 * - GET  /api/states — Indian states dropdown data
 * - GET  /api/occupations — Occupation dropdown data
 * - GET  /api/consistency-options — Bill consistency dropdown data
 * 
 * All dropdown data is served via API endpoints (not hardcoded in HTML).
 * 
 * @author FinScore AI Team
 */
@RestController
@RequestMapping("/api")
@Slf4j
@RequiredArgsConstructor
public class CreditController {

    private final CreditScoringService creditScoringService;
    private final GeminiService geminiService;
    private final BorrowerRepository borrowerRepository;
    private final ObjectMapper objectMapper;

    // ═══ CREDIT SCORING ENDPOINTS ═══════════════════════════════════════

    /**
     * POST /api/credit/score — Process a credit assessment
     * 
     * Full pipeline:
     * 1. Validate consent flag
     * 2. Call Python ML service for XGBoost prediction
     * 3. Call Gemini API for explanation
     * 4. Call RAG pipeline for financial tips
     * 5. Save to MySQL
     * 6. Return CreditResult
     */
    @PostMapping("/credit/score")
    public ResponseEntity<?> processScore(
            @Valid @RequestBody BorrowerInput input,
            @RequestHeader(value = "X-Forwarded-For", required = false) String forwardedFor,
            @RequestHeader(value = "X-Real-IP", required = false) String realIp) {

        try {
            // Record IP address for audit (prefer forwarded header for proxied requests)
            String ip = forwardedFor != null ? forwardedFor.split(",")[0].trim() 
                       : (realIp != null ? realIp : "unknown");
            input.setIpAddress(ip);

            // Process the assessment
            CreditResult result = creditScoringService.processAssessment(input);

            log.info("Assessment completed: ID={}, Score={}, Risk={}", 
                     result.getId(), result.getCreditScore(), result.getRiskCategory());

            return ResponseEntity.ok(result);

        } catch (IllegalArgumentException e) {
            // Consent not given or validation failure
            log.warn("Validation error: {}", e.getMessage());
            return ResponseEntity.badRequest().body(Map.of(
                "error", e.getMessage(),
                "field", "consentGiven"
            ));
        } catch (Exception e) {
            log.error("Assessment processing failed: {}", e.getMessage(), e);
            return ResponseEntity.internalServerError().body(Map.of(
                "error", "An error occurred while processing your assessment. Please try again.",
                "details", e.getMessage()
            ));
        }
    }

    /**
     * POST /api/credit/explain — Re-generate explanation in different language
     * 
     * Allows users to toggle between Hindi and English explanations
     * on the result page without re-running the full assessment.
     */
    @PostMapping("/credit/explain")
    public ResponseEntity<?> toggleExplanation(@RequestBody Map<String, Object> request) {
        try {
            Long scoreId = Long.valueOf(request.get("scoreId").toString());
            String language = (String) request.getOrDefault("language", "English");

            // Fetch the saved assessment
            Optional<BorrowerInput> optionalInput = borrowerRepository.findById(scoreId);
            if (optionalInput.isEmpty()) {
                return ResponseEntity.notFound().build();
            }

            BorrowerInput saved = optionalInput.get();

            // Check if we already have the explanation in this language cached
            String cachedExplanation = "Hindi".equalsIgnoreCase(language) 
                ? saved.getGeminiExplanationHi() 
                : saved.getGeminiExplanationEn();

            if (cachedExplanation != null && !cachedExplanation.isEmpty()) {
                return ResponseEntity.ok(Map.of("explanation", cachedExplanation));
            }

            // Generate fresh explanation via Gemini
            String explanation = geminiService.generateExplanation(
                saved.getOccupation(),
                saved.getState(),
                saved.getMonthlyIncome().intValue(),
                saved.getCreditScore(),
                saved.getRiskCategory(),
                saved.getLoanRequested().intValue(),
                language
            );

            // Cache the new explanation
            if ("Hindi".equalsIgnoreCase(language)) {
                saved.setGeminiExplanationHi(explanation);
            } else {
                saved.setGeminiExplanationEn(explanation);
            }
            borrowerRepository.save(saved);

            return ResponseEntity.ok(Map.of("explanation", explanation));

        } catch (Exception e) {
            log.error("Explanation toggle failed: {}", e.getMessage());
            return ResponseEntity.internalServerError().body(Map.of(
                "error", "Failed to generate explanation. Please try again."
            ));
        }
    }

    /**
     * GET /api/credit/history — Paginated assessment history
     * 
     * Supports filtering by state, occupation, and risk category.
     * Used by the dashboard table and chart data.
     */
    @GetMapping("/credit/history")
    public ResponseEntity<?> getHistory(
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size,
            @RequestParam(required = false) String state,
            @RequestParam(required = false) String occupation,
            @RequestParam(required = false) String riskCategory) {

        try {
            PageRequest pageRequest = PageRequest.of(page, size, Sort.by("createdAt").descending());
            Page<BorrowerInput> results;

            // Apply filters if provided
            if (state != null && !state.isEmpty() && occupation != null && !occupation.isEmpty()) {
                results = borrowerRepository.findByStateAndOccupation(state, occupation, pageRequest);
            } else if (state != null && !state.isEmpty()) {
                results = borrowerRepository.findByState(state, pageRequest);
            } else if (occupation != null && !occupation.isEmpty()) {
                results = borrowerRepository.findByOccupation(occupation, pageRequest);
            } else if (riskCategory != null && !riskCategory.isEmpty()) {
                results = borrowerRepository.findByRiskCategory(riskCategory, pageRequest);
            } else {
                results = borrowerRepository.findAllByOrderByCreatedAtDesc(pageRequest);
            }

            // Build response with pagination metadata
