package com.finscore.config;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.client.RestTemplate;
import org.springframework.web.servlet.config.annotation.CorsRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/**
 * AppConfig — Application Bean Configuration
 * ==============================================
 * Configures shared beans used across the application:
 * - RestTemplate for external API calls (ML service, Gemini)
 * - ObjectMapper with Java 8 time support
 * - CORS configuration for API access
 * 
 * @author FinScore AI Team
 */
@Configuration
public class AppConfig {

    /**
     * RestTemplate bean for HTTP calls to:
     * - Python ML service (localhost:8000)
     * - Google Gemini API
     */
    @Bean
    public RestTemplate restTemplate() {
        return new RestTemplate();
    }

    /**
     * ObjectMapper configured with Java 8 date/time support.
     * Handles LocalDateTime serialization for API responses.
     */
    @Bean
    public ObjectMapper objectMapper() {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new JavaTimeModule());
        mapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
        return mapper;
    }

    /**
     * CORS configuration allowing frontend JavaScript to call
     * API endpoints from the same origin.
     */
    @Bean
    public WebMvcConfigurer corsConfigurer() {
        return new WebMvcConfigurer() {
            @Override
            public void addCorsMappings(CorsRegistry registry) {
                registry.addMapping("/api/**")
                        .allowedOrigins("*")
                        .allowedMethods("GET", "POST", "PUT", "DELETE", "OPTIONS")
                        .allowedHeaders("*");
            }
        };
    }
}

package com.finscore.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.web.SecurityFilterChain;

/**
 * SecurityConfig — Spring Security Configuration
 * ==================================================
 * Configures authentication and authorization rules:
 * 
 * PUBLIC (no login required):
 * - /          (home page)
 * - /form      (assessment form)
 * - /result/** (result pages)
 * - /api/**    (REST API endpoints except dashboard)
 * - /css/**    (static CSS)
 * - /js/**     (static JS)
 * - /h2-console/** (H2 console for dev)
 * 
 * PROTECTED (login required):
 * - /dashboard         (admin dashboard page)
 * - /api/dashboard/**  (dashboard API endpoints)
 * 
 * Authentication uses HTTP Basic with credentials from
 * environment variables (ADMIN_USERNAME, ADMIN_PASSWORD).
 * 
 * @author FinScore AI Team
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            // ─── Authorization Rules ────────────────────────────────
            .authorizeHttpRequests(auth -> auth
                // Public pages — accessible to everyone
                .requestMatchers("/", "/form", "/result/**").permitAll()

                // Public API endpoints — form dropdowns, scoring, history
                .requestMatchers("/api/states", "/api/occupations", 
                                 "/api/consistency-options").permitAll()
                .requestMatchers("/api/credit/**").permitAll()

                // Static resources
                .requestMatchers("/css/**", "/js/**", "/images/**", 
                                 "/favicon.ico").permitAll()

                // H2 console (development only)
                .requestMatchers("/h2-console/**").permitAll()

                // Dashboard — requires authentication
                .requestMatchers("/dashboard", "/api/dashboard/**").authenticated()

                // Everything else requires authentication
                .anyRequest().authenticated()
            )

            // ─── Authentication ─────────────────────────────────────
            // HTTP Basic for API calls + form login for browser access
            .httpBasic(basic -> {})
            .formLogin(form -> form
                .defaultSuccessUrl("/dashboard", true)
                .permitAll()
            )
            .logout(logout -> logout
                .logoutSuccessUrl("/")
                .permitAll()
            )

            // ─── CSRF ───────────────────────────────────────────────
            // Disable CSRF for API endpoints (they use JSON, not forms)
            // Keep CSRF for form submissions via Thymeleaf
            .csrf(csrf -> csrf
                .ignoringRequestMatchers("/api/**", "/h2-console/**")
            )

            // ─── Frame Options ──────────────────────────────────────
            // Allow H2 console to use frames (dev only)
            .headers(headers -> headers
                .frameOptions(frame -> frame.sameOrigin())
            );

        return http.build();
    }
}

