211:      * functional even if the Python service is temporarily down.
212:      */
213:     private Map<String, Object> fallbackScoring(BorrowerInput input) {
214:         log.warn("Using fallback scoring — ML service unavailable");
215:         
216:         double incomeNorm = Math.min(input.getMonthlyIncome().doubleValue() / 50000.0, 1.0);
217:         double upiNorm = Math.min(input.getUpiFrequency() / 100.0, 1.0);
218:         double upiAmtNorm = Math.min(input.getAvgUpiAmount().doubleValue() / 5000.0, 1.0);
219:         
220:         double utilityScore = switch (input.getUtilityConsistency()) {
221:             case "Always on time" -> 1.0;
222:             case "Sometimes late" -> 0.5;
223:             default -> 0.15;
224:         };
225:         
226:         double rechargeNorm = Math.min(input.getRechargeAmount().doubleValue() / 500.0, 1.0);
227:         
228:         double rawScore = 0.25 * incomeNorm + 0.20 * upiNorm + 0.15 * upiAmtNorm 
229:                         + 0.20 * utilityScore + 0.10 * rechargeNorm + 0.10 * 0.5;
230:         
231:         int score = (int) Math.min(Math.max(rawScore * 100, 0), 100);
232:         String risk = score >= 70 ? "Low Risk" : (score >= 40 ? "Medium Risk" : "High Risk");
233:         boolean eligible = score >= 30;
234:         double maxLoan = eligible 
235:             ? Math.min(input.getMonthlyIncome().doubleValue() * (6 + score * 0.18), 
236:                        input.getLoanRequested().doubleValue()) 
237:             : 0;
238:         
239:         String interestRate = score >= 70 ? "10-12% p.a." 
240:             : (score >= 50 ? "14-16% p.a." : (score >= 30 ? "18-22% p.a." : "Not recommended"));
241: 
242:         Map<String, Object> result = new HashMap<>();
